+"""Starlark representation of locked requirements.
+
+@generated by rules_python pip.parse bzlmod extension.
+"""
+
+load("@rules_python//python:pip.bzl", "pip_utils")
+
+all_requirements = ["@@rules_python++pip+bazel_pip_dev_deps//bazel_runfiles:pkg"]
+
+all_whl_requirements_by_package = {
+    "bazel_runfiles": "@@rules_python++pip+bazel_pip_dev_deps//bazel_runfiles:whl",
+}
+
+all_whl_requirements = all_whl_requirements_by_package.values()
+
+all_data_requirements = ["@@rules_python++pip+bazel_pip_dev_deps//bazel_runfiles:data"]
+
+def requirement(name):
+    return "@@rules_python++pip+bazel_pip_dev_deps//{}:{}".format(pip_utils.normalize_name(name), "pkg")
+
+def whl_requirement(name):
+    return "@@rules_python++pip+bazel_pip_dev_deps//{}:{}".format(pip_utils.normalize_name(name), "whl")
+
+def data_requirement(name):
+    return "@@rules_python++pip+bazel_pip_dev_deps//{}:{}".format(pip_utils.normalize_name(name), "data")
+
